# สร้าง seed.sql จากข้อมูลตั้งต้น (เช็กลิสต์ 13 หมวด + คำแปล 3 ภาษา ฉบับร่าง)
import json, secrets

def T(th, my, km, lo): return {'text': th, 't': {'my': my, 'km': km, 'lo': lo}}

def item(code, th, my, km, lo, crit=False, na=False, lsr=None, ill=None, setup=False):
    d = {'code': code, **T(th, my, km, lo), 'crit': crit}
    if na: d['na'] = True
    if lsr: d['lsr'] = lsr
    if ill: d['ill'] = ill
    if setup: d['setup'] = True
    return d

def rule(code, th, my, km, lo, ill=None):
    d = {'code': code, **T(th, my, km, lo)}
    if ill: d['ill'] = ill
    return d

