def q(s): return "'" + s.replace("'", "''") + "'"

out = ['-- SafeStart v2 · ค่าตั้งต้น (สร้างจาก gen_seed.py) · รันหลัง schema.sql',
       '-- ก่อนรัน: แก้อีเมลผู้ดูแลระบบในบรรทัด invites ด้านล่าง', '']
out.append(f"insert into app_secrets(key,value) values('id_salt',encode(extensions.gen_random_bytes(32),'hex')) on conflict (key) do nothing;")
for k, v in SETTINGS.items():
    out.append(f"insert into settings(scg_company_id,key,value) values(null,{q(k)},{q(json.dumps(v, ensure_ascii=False))}::jsonb) on conflict (scg_company_id,key) do update set value=excluded.value;")
out.append('')
out.append('do $$ declare c uuid; g uuid; begin')
for name, short, color, groups in COMPANIES:
    out.append(f"  insert into scg_companies(name,short,color) values({q(name)},{q(short)},{q(color)}) returning id into c;")
    for i, (gname, types) in enumerate(groups):
        out.append(f"  insert into install_groups(scg_company_id,name,sort) values(c,{q(gname)},{i}) returning id into g;")
        for tname, hz in types:
            ex = EXTRA.get(tname, [])
            out.append(f"  insert into job_types(scg_company_id,group_id,name,hazards,extra) values(c,g,{q(tname)},'{{{','.join(hz)}}}','{{{','.join(ex)}}}');")
out.append('end $$;')
out.append('')
out.append("-- ผู้ดูแลระบบ (System owner): สร้างบริษัท SCG และเชิญ Safety Admin คนแรกของแต่ละบริษัท · ไม่เห็นข้อมูลงาน")
out.append("insert into invites(email,full_name,role,is_owner,scg_company_ids) values('CHANGE_ME@scg.com','ผู้ดูแลระบบ','safety_admin',true,")
out.append("  (select array_agg(id) from scg_companies)) on conflict (email) do nothing;")
out.append("")
out.append("-- ผู้ใช้ที่เคยเข้าระบบรุ่นก่อน: สร้างโปรไฟล์ใหม่ตามคำเชิญ (ไม่มีคำเชิญ = รอสิทธิ์)")
out.append("insert into profiles(id,email,full_name,role,scg_company_ids,contractor_id,is_owner)")
out.append("select u.id,lower(u.email),i.full_name,coalesce(i.role,'pending'),coalesce(i.scg_company_ids,'{}'),i.contractor_id,coalesce(i.is_owner,false)")
out.append("from auth.users u left join invites i on lower(i.email)=lower(u.email) on conflict (id) do nothing;")
open('seed.sql', 'w').write('\n'.join(out) + '\n')
json.dump(SETTINGS, open('../test/settings.json', 'w'), ensure_ascii=False)
